	{
		flushMemory();
		view = new View();
		monitor.reset();
		roster.clear();
		boat.clear();
		wrecks.clear();
		events.reset();
		hookWatch.reset();
		crewSwap.reset();
		activity.reset();
		countdown.reset();
		rate = new SalvageRateModel();
		rateWreck = null;
		aboard = false;
		lastContainerTick = Integer.MIN_VALUE;
		fullLineTick = Integer.MIN_VALUE;
		inventoryKnown = false;
		inventorySalvage = 0;
		freeInventorySlots = INVENTORY_SLOTS;
		occupiedInventorySlots = 0;
		inventorySalvageTypes = Collections.emptySet();
		hookedInInventory = 0;
		pendingHoldTicks = 0;
		pendingWithdraw = false;
		inventoryChanged = false;
		sortingFinishTick = -1;
		lastActivity = PlayerActivity.IDLE;
		lastBoatPoint = null;
		stillTicks = 0;
		hazardous = false;
		hazardAt = null;
		waitingSince = -1;
		worldTipGiven = false;
		waitingNotified = false;
		sortingDoneAt = -1;
		boostDropNotified = false;
