		titleRow.add(links, BorderLayout.EAST);
		titleRow.setAlignmentX(LEFT_ALIGNMENT);
		titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, LINK_BUTTON_SIZE));
		top.add(titleRow);
		top.add(Box.createVerticalStrut(6));
